370	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
371	  /// (Boundaries: "keyed by the user message's persisted id") — calls
372	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
373	  /// full [ChatRepository.sendMessage] resend of that same user content
374	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
375	  /// retry, no `serverId`" — the stream dropped before `message_created`
376	  /// ever arrived, so the backend never actually persisted the question;
377	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
378	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
379	  /// is in flight"), so this is a no-op while a send/retry is already in
380	  /// flight — and, like [sendMessage] (review finding), a no-op while
381	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
382	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
383	  /// alone, so it needs this exact same guard to honor the offline banner.
384	  Future<void> retryMessage(String aiMessageId) async {
385	    final current = state;
386	    if (current is! ChatReady) {
387	      return;
388	    }
389	    if (_isSending || current.isOffline) {
390	      return;
391	    }
392	    final messages = current.messages;
393	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
394	    // Review finding: defensively checks `role` too, even though only an
395	    // assistant message ever reaches `failed` status today — matches this
396	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
397	    // not-found/structurally-impossible case).
398	    if (aiIndex == -1 ||
399	        messages[aiIndex].role != ChatMessageRole.assistant ||
400	        messages[aiIndex].status != ChatMessageStatus.failed) {
401	      return;
402	    }
403	    ChatUiMessage? userMessage;
404	    for (var i = aiIndex - 1; i >= 0; i--) {
405	      if (messages[i].role == ChatMessageRole.user) {
406	        userMessage = messages[i];
407	        break;
408	      }
409	    }
410	    if (userMessage == null) {
411	      return;
412	    }
413	
414	    _isSending = true;
415	    emit(
416	      current.copyWith(
417	        messages: [
418	          for (final message in current.messages)
419	            if (message.id == aiMessageId)
420	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
421	            else
422	              message,
423	        ],
424	        isSending: true,
425	      ),
426	    );
427	
428	    final serverId = userMessage.serverId;
429	    final stream = serverId == null
430	        ? _repository.sendMessage(current.sessionId, userMessage.content)
431	        : _repository.retryMessage(current.sessionId, serverId);
432	    await _consumeStream(
433	      stream,
434	      userMessageId: userMessage.id,
435	      aiMessageId: aiMessageId,
436	    );
437	  }
438	
439	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
440	  /// helper" extends to this subscribe-and-wait shape too, not just
441	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
442	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
443	  /// resolves once the stream ends (`done`, an in-band error, or a
444	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
445	  /// either way via [_finishSending].
446	  Future<void> _consumeStream(
447	    Stream<Either<Failure, ChatStreamEvent>> stream, {
448	    required String userMessageId,
449	    required String aiMessageId,
450	  }) async {
451	    await _sendSubscription?.cancel();
452	    final completer = Completer<void>();
453	    _sendCompleter = completer;
454	    _sendSubscription = stream.listen(
455	      (event) {
456	        event.match(
457	          (failure) => _markFailed(aiMessageId),
458	          (streamEvent) =>
459	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
460	        );
461	      },
462	      onError: (Object _, StackTrace _) {
